  -- Turma DH26-7A ---------------------------------------------------------------
  SELECT gl.id INTO v_gl FROM public.grade_levels gl JOIN public.programs p ON p.id = gl.program_id
   WHERE gl.school_id = v_school AND gl.is_active AND p.code = 'ESG1' AND gl.code = '7CL' LIMIT 1;
  IF v_gl IS NULL THEN
    SELECT id INTO v_gl FROM public.grade_levels WHERE school_id = v_school AND is_active AND sequence = 7 ORDER BY created_at LIMIT 1;
  END IF;
  IF v_gl IS NULL THEN RAISE EXCEPTION 'Sem classe 7 activa para a turma DH26-7A.'; END IF;
