  VALUES ('8cf45512-fda8-29fe-4a26-bc15978f8bec', v_school, v_year, '529be39d-947d-880e-118e-667bb2c67475', 'Exames de recurso', '', 'event', DATE '2027-07-12', DATE '2027-07-16', NULL, NULL, 'all', false, 'published', v_actor, v_actor) ON CONFLICT (id) DO NOTHING;
  -- Sessões de exame -----------------------------------------------------------------
  INSERT INTO public.siga_exam_sessions (id, school_id, academic_year_id, kind, name, starts_on, ends_on, max_failed_subjects, result_method, status, created_by, updated_by)
  VALUES ('36befb03-0522-ec42-be85-713ca1496dd9', v_school, v_year, 'exame_final', 'Exames finais 2026/2027 (demonstração)', DATE '2027-06-21', DATE '2027-07-02', 3, 'average', 'draft', v_actor, v_actor) ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.siga_exam_sessions (id, school_id, academic_year_id, kind, name, starts_on, ends_on, max_failed_subjects, result_method, status, created_by, updated_by)
  VALUES ('9bf59a3a-6250-f967-6532-971c23ba81ab', v_school, v_year, 'recurso', 'Exames de recurso 2026/2027 (demonstração)', DATE '2027-07-12', DATE '2027-07-16', 3, 'replace', 'draft', v_actor, v_actor) ON CONFLICT (id) DO NOTHING;

  SELECT format('salas=%s professores=%s turmas=%s alunos=%s disciplinas=%s aulas=%s horários publicados=%s (novos nesta corrida=%s) provas=%s notas=%s trabalhos=%s entregas=%s eventos=%s',
    (SELECT count(*) FROM public.rooms WHERE school_id = v_school AND code LIKE 'DH26-%'),
    (SELECT count(DISTINCT cs.teacher_id) FROM public.class_subjects cs WHERE cs.class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475')),
    (SELECT count(*) FROM public.class_groups WHERE id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475')),
    (SELECT count(*) FROM public.enrollments WHERE class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475') AND status = 'active'),
    (SELECT count(*) FROM public.class_subjects WHERE class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475')),
    (SELECT count(*) FROM public.timetable_slots t JOIN public.class_subjects cs ON cs.id = t.class_subject_id WHERE cs.class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475') AND t.status = 'active' AND t.schedule_id IS NOT NULL),
    (SELECT count(*) FROM public.academic_schedules WHERE class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475') AND status = 'published'),
    v_published,
    (SELECT count(*) FROM public.siga_assessment_items WHERE class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475')),
    (SELECT count(*) FROM public.siga_assessment_scores s JOIN public.siga_assessment_items i ON i.id = s.item_id WHERE i.class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475')),
    (SELECT count(*) FROM public.siga_class_tasks t JOIN public.class_subjects cs ON cs.id = t.class_subject_id WHERE cs.class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475')),
    (SELECT count(*) FROM public.siga_class_task_submissions s JOIN public.siga_class_tasks t ON t.id = s.task_id JOIN public.class_subjects cs ON cs.id = t.class_subject_id WHERE cs.class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475')),
    (SELECT count(*) FROM public.siga_calendar_events WHERE class_group_id IN ('5745226b-2490-1739-306e-feef6aaad823', '529be39d-947d-880e-118e-667bb2c67475'))
  ) INTO v_counts;
  IF c_dry_run THEN
    RAISE EXCEPTION 'ENSAIO OK (nada gravado): %', v_counts;
  END IF;
  RAISE NOTICE 'Demonstração DH26 pronta: %', v_counts;
END
$seed$;
